CREATE TABLE local_restaurant_attempts (id TEXT PRIMARY KEY NOT NULL, order_id TEXT NOT NULL REFERENCES local_restaurant_orders(id), parent_id TEXT NOT NULL REFERENCES local_restaurant_attempts(id), request TEXT NOT NULL);
CREATE TABLE local_restaurant_control (order_id TEXT PRIMARY KEY NOT NULL REFERENCES local_restaurant_orders(id), parent_id TEXT NOT NULL REFERENCES local_restaurant_attempts(id), attempt_id TEXT NOT NULL UNIQUE REFERENCES local_restaurant_attempts(id), actor_id TEXT NOT NULL REFERENCES local_principals(id), revision INTEGER NOT NULL CHECK(revision>0), phase TEXT NOT NULL CHECK(phase IN ('editable','bound','submitting','refused','unknown','settled')), reason TEXT NOT NULL);
CREATE TABLE local_restaurant_recovery_events (sequence INTEGER PRIMARY KEY AUTOINCREMENT, order_id TEXT NOT NULL, actor_id TEXT NOT NULL, payload TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TRIGGER local_restaurant_attempts_no_update BEFORE UPDATE ON local_restaurant_attempts BEGIN SELECT RAISE(ABORT,'Attempts are immutable'); END;
CREATE TRIGGER local_restaurant_attempts_no_delete BEFORE DELETE ON local_restaurant_attempts BEGIN SELECT RAISE(ABORT,'Attempts are immutable'); END;
CREATE TRIGGER local_restaurant_recovery_events_no_update BEFORE UPDATE ON local_restaurant_recovery_events BEGIN SELECT RAISE(ABORT,'Recovery audit is immutable'); END;
CREATE TRIGGER local_restaurant_recovery_events_no_delete BEFORE DELETE ON local_restaurant_recovery_events BEGIN SELECT RAISE(ABORT,'Recovery audit is immutable'); END;
CREATE TRIGGER local_restaurant_control_revision BEFORE UPDATE ON local_restaurant_control WHEN NEW.order_id<>OLD.order_id OR NEW.parent_id<>OLD.parent_id OR NEW.revision<>OLD.revision+1 OR OLD.phase='settled' BEGIN SELECT RAISE(ABORT,'Stale or settled checkout'); END;
CREATE TRIGGER local_restaurant_control_settled_guard BEFORE UPDATE ON local_restaurant_control WHEN NEW.phase='settled' AND NOT EXISTS(SELECT 1 FROM local_restaurant_orders WHERE id=NEW.order_id AND settled_invoice=NEW.attempt_id) BEGIN SELECT RAISE(ABORT,'Paid state requires the settled invoice'); END;
INSERT INTO local_restaurant_attempts SELECT invoice_id,order_id,invoice_id,request FROM local_restaurant_bindings;
INSERT INTO local_restaurant_control SELECT b.order_id,b.invoice_id,b.invoice_id,b.actor_id,1,CASE WHEN o.settled_invoice IS NULL THEN 'unknown' ELSE 'settled' END,'' FROM local_restaurant_bindings b JOIN local_restaurant_orders o ON o.id=b.order_id;
DROP TRIGGER local_restaurant_settle_guard;
CREATE TRIGGER local_restaurant_settle_guard BEFORE UPDATE OF settled_invoice ON local_restaurant_orders WHEN OLD.settled_invoice IS NOT NULL OR NOT EXISTS(SELECT 1 FROM local_restaurant_attempts a JOIN local_restaurant_control c ON c.order_id=a.order_id AND c.attempt_id=a.id JOIN local_invoices i ON i.id=a.id WHERE a.order_id=OLD.id AND i.id=NEW.settled_invoice) BEGIN SELECT RAISE(ABORT,'Settlement requires current attempt invoice'); END;
PRAGMA user_version=16;
